-- Correct 2026 SGP monthly forecast quantities for Atlantic Precision Resource.
-- Source: Forecasts 2026 SGP tab in 2026 SGP GMPA Forecast Worksheet - Analysis UPDATE - 2Q26.
-- Scope: updates only sgpForecastQty for worksheet rows; preserves all existing app-only lines, actualQty, forecastQty, and adjustedQty.
-- Inserts worksheet-only lines with empty actual/forecast values.
-- Expected worksheet rows: 602. Expected result against the reviewed production snapshot: 589 updates + 13 inserts; existing app-only rows remain.

BEGIN;

CREATE TEMP TABLE sgp_corrected_load (
  customer_id text NOT NULL,
  customer_name text NOT NULL,
  customer_group text NOT NULL,
  customer_part_number text NOT NULL,
  item_sku text NOT NULL,
  team text NOT NULL,
  csr text NOT NULL,
  production_type text NOT NULL,
  status_flag text NOT NULL,
  annual_base_qty double precision NOT NULL,
  qty jsonb NOT NULL,
  sort_order integer NOT NULL
) ON COMMIT DROP;


DO $$
DECLARE
  company_id text;
  source_rows integer;
  matched_rows integer;
BEGIN
  SELECT id INTO STRICT company_id FROM "Company" WHERE name = 'Atlantic Precision Resource';
  SELECT COUNT(*) INTO source_rows FROM sgp_corrected_load;
  IF source_rows <> 602 THEN
    RAISE EXCEPTION 'Expected 602 worksheet rows, found %.', source_rows;
  END IF;

    "id", "companyId", "year", "customerId", "customerName", "customerGroup", "customerPartNumber",
    "itemSku", "team", "csr", "productionType", "statusFlag", "annualBaseQty",
    "forecastQty", "sgpForecastQty", "actualQty", "adjustedQty", "sortOrder", "createdAt", "updatedAt"
  )
  SELECT
    'sgp26_' || substr(md5(company_id || '|' || s.customer_id || '|' || s.item_sku || '|' || s.customer_part_number), 1, 22),
    company_id, 2026, s.customer_id, s.customer_name, NULLIF(s.customer_group, ''), s.customer_part_number,
    s.item_sku, NULLIF(s.team, ''), NULLIF(s.csr, ''), NULLIF(s.production_type, ''), NULLIF(s.status_flag, ''), s.annual_base_qty,
    '{}'::jsonb, s.qty, '{}'::jsonb, '{}'::jsonb, s.sort_order, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
  FROM sgp_corrected_load s
  ON CONFLICT ("companyId", "year", "customerId", "itemSku", "customerPartNumber") DO UPDATE SET
    "sgpForecastQty" = EXCLUDED."sgpForecastQty",
    "updatedAt" = CURRENT_TIMESTAMP;

  SELECT COUNT(*) INTO matched_rows
  FROM "ProductRevenueForecastLine" l
  JOIN sgp_corrected_load s
    ON TRIM(l."customerId") = s.customer_id
   AND TRIM(l."itemSku") = s.item_sku
   AND UPPER(TRIM(l."customerPartNumber")) = UPPER(s.customer_part_number)
  WHERE l."companyId" = company_id AND l."year" = 2026;
  IF matched_rows <> source_rows THEN
    RAISE EXCEPTION 'Expected % corrected worksheet lines after upsert, found %.', source_rows, matched_rows;
  END IF;
END $$;

COMMIT;

-- Verification: worksheet rows must all be present; existing app-only lines are retained.
SELECT
  COUNT(*) AS total_app_lines,
  COUNT(*) FILTER (WHERE l."id" LIKE 'sgp26_%') AS inserted_by_corrected_load,
  SUM((SELECT COALESCE(SUM(value::numeric), 0) FROM jsonb_each_text(l."sgpForecastQty") e)) AS total_sgp_units
FROM "ProductRevenueForecastLine" l
WHERE l."companyId" = (SELECT id FROM "Company" WHERE name = 'Atlantic Precision Resource')
  AND l."year" = 2026;
